<template><view class="post-page"><view class="nav"><text @tap="back" class="cuIcon-close"/><text>新建投稿</text><text @tap="submit" class="send">提交审核</text></view><scroll-view scroll-y class="scroll"><view class="form"><text class="label">文章标题</text><input v-model="title" class="title" maxlength="120" placeholder="给这篇文章一个标题"/><input v-model="subtitle" class="subtitle" maxlength="160" placeholder="副标题或一句话导语（可选）"/><view class="row"><view @tap="chooseJournal"><text class="label">投稿刊物</text><text>{{journalName||'选择刊物'}} ·</text></view><view @tap="layoutPicker=true"><text class="label">文章版式</text><text>{{layoutLabel}} ·</text></view></view><text class="label">阅读主题</text><scroll-view scroll-x class="themes"><text v-for="item in themes" :key="item.value" :class="{active:theme===item.value}" @tap="theme=item.value">{{item.label}}</text></scroll-view><view class="editor-head"><text class="label">正文 Markdown</text><text @tap="preview=!preview">{{preview?'编辑':'预览'}}</text></view><textarea v-if="!preview" v-model="body" class="editor" maxlength="60000" placeholder="从这里开始写下你的文章…\n\n支持 Markdown 标题、引用、图片和分隔线。"/><view v-else class="preview"><text class="preview-title">{{title||'未命名文章'}}</text><mp-html :content="body||'写下正文后，这里会显示预览。'" :markdown="true"/></view><text class="tip">投稿进入独立编辑部审核，不会发布为普通帖子。</text></view></scroll-view><view v-if="layoutPicker" class="modal" @tap="layoutPicker=false"><view class="sheet" @tap.stop><text class="sheet-title">选择文章版式</text><view class="layouts"><view v-for="item in layouts" :key="item.value" :class="{active:layout===item.value}" @tap="layout=item.value;layoutPicker=false"><text>{{item.label}}</text><small>{{item.desc}}</small></view></view></view></view></view></template>
<script>
import mpHtml from '@/components/mp-html/mp-html';import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js'
export default {components:{mpHtml},data(){return {title:'',subtitle:'',summary:'',body:'',journalId:0,journalName:'',journals:[],layout:'classic',theme:'paper',preview:false,layoutPicker:false,themes:[{value:'white',label:'极简白'},{value:'paper',label:'杂志米白'},{value:'gray',label:'纸张灰'},{value:'night',label:'深夜黑'},{value:'editorial',label:'编辑部'}],layouts:[{value:'classic',label:'经典杂志',desc:'首字下沉 · 引用清晰'},{value:'modern',label:'现代编辑',desc:'大标题 · 强分隔'},{value:'minimal',label:'极简阅读',desc:'窄栏 · 大留白'},{value:'photo',label:'影像叙事',desc:'大图 · 图注优先'}]}},computed:{layoutLabel(){let x=this.layouts.find(v=>v.value===this.layout);return x?x.label:'经典杂志'}},onLoad(q){this.journalId=Number(q.journalId||0);this.journalName=q.journalName||'';this.loadJournals()},methods:{token(){try{return JSON.parse(localStorage.getItem('userinfo')||'{}').token||localStorage.getItem('token')||''}catch(e){return ''}},loadJournals(){this.$Net.request({url:this.$API.journalList(),data:{page:1,limit:50},method:'get',dataType:'json',success:r=>{this.journals=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[];if(!this.journalId&&this.journals[0]){this.journalId=this.journals[0].id;this.journalName=this.journals[0].name}}})},chooseJournal(){if(!this.journals.length)return uni.showToast({title:'暂无可投稿刊物',icon:'none'});uni.showActionSheet({itemList:this.journals.map(v=>v.name),success:r=>{let x=this.journals[r.tapIndex];this.journalId=x.id;this.journalName=x.name}})},back(){uni.navigateBack({delta:1})},submit(){if(!this.token())return uni.navigateTo({url:'/pages/user/login'});if(this.title.trim().length<5)return uni.showToast({title:'标题至少需要5个字',icon:'none'});if(this.body.replace(/\s/g,'').length<20)return uni.showToast({title:'正文至少需要20个字',icon:'none'});if(!this.journalId)return uni.showToast({title:'请选择投稿刊物',icon:'none'});uni.showLoading({title:'提交中'});this.$Net.request({url:this.$API.journalArticleSubmit(),data:{token:this.token(),params:JSON.stringify({journalId:this.journalId,title:this.title.trim(),subtitle:this.subtitle,summary:this.summary,bodyMarkdown:this.body,layoutPreset:this.layout,themePreset:this.theme})},method:'post',dataType:'json',success:r=>{uni.hideLoading();if(r.data&&r.data.code===1){uni.showModal({title:'投稿已提交',content:'文章已进入编辑部审核。',showCancel:false,success:()=>this.back()})}else uni.showToast({title:r.data&&r.data.msg||'提交失败',icon:'none'})},fail:()=>{uni.hideLoading();uni.showToast({title:'网络不太好，请稍后重试',icon:'none'})}})}}}
</script>
<style scoped>.post-page{min-height:100vh;background:#f4f1eb;color:#1b2c27}.nav{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;padding:calc(22px + env(safe-area-inset-top)) 22px 16px;background:rgba(244,241,235,.94);font:20px Georgia,serif}.send{padding:8px 12px;border-radius:18px;background:#345f50;color:#fff;font:12px sans-serif}.scroll{height:calc(100vh - 78px)}.form{max-width:900px;margin:auto;padding:35px 24px 70px}.label{display:block;margin:14px 0 10px;font-size:11px;letter-spacing:1.7px;color:#a0744c;text-transform:uppercase}.title{width:100%;font:38px Georgia,serif;color:#203c35}.subtitle{width:100%;margin-top:12px;color:#71817a}.row{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:32px 0;padding:17px 0;border-top:1px solid #d8dfd9;border-bottom:1px solid #d8dfd9}.row view text:last-child{display:block;color:#476b5d}.themes{white-space:nowrap}.themes text{display:inline-block;padding:12px 14px;margin-right:7px;border:1px solid #d3ddd5;border-radius:7px;font-size:12px}.themes text.active{border:2px solid #a9744e}.editor-head{display:flex;justify-content:space-between;margin-top:32px}.editor-head>text:last-child{color:#567f70}.editor{box-sizing:border-box;width:100%;min-height:55vh;padding:18px;margin-top:12px;border:1px solid #d5ded7;border-radius:8px;background:#fffaf5;font-size:17px;line-height:1.9}.preview{margin-top:12px;padding:22px;border:1px solid #d5ded7;border-radius:8px;background:#fffaf5;line-height:1.8}.preview-title{display:block;margin-bottom:20px;font:34px Georgia,serif}.tip{display:block;margin-top:14px;color:#899790;font-size:12px}.modal{position:fixed;inset:0;z-index:5;display:flex;align-items:flex-end;background:#17241f55}.sheet{width:100%;padding:25px 20px 40px;border-radius:22px 22px 0 0;background:#f8f6f1}.sheet-title{font:22px Georgia,serif}.layouts{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px}.layouts view{padding:16px;border:1px solid #dce5df;border-radius:9px}.layouts view.active{border:2px solid #a9744e}.layouts text,.layouts small{display:block}.layouts small{margin-top:6px;color:#8b9a93;font-size:11px}@media(max-width:480px){.title{font-size:32px}}
</style>
